// Title must be a valid, null-terminated UTF-8 string
std::string titleStr = FUZZ_PARAM_STR();
const char *title = titleStr.c_str();

// Call InitWindow per API; only one active window at a time is supported.
// If a window is already marked ready in global state, bail to respect single-window constraint.
if (FUZZ_GET_ATTR_INT_GLOBAL("window_ready")) { FUZZ_BAIL(); }
InitWindow(w, h, title);

// Validate window got ready
bool ready = IsWindowReady();
if (!ready) { FUZZ_BAIL(); }

// Track global window state for downstream stubs
FUZZ_SET_ATTR_INT_GLOBAL("window_ready", 1);
// No outputs; window/context is global state.

// Require an initialized window before closing
if (!FUZZ_GET_ATTR_INT_GLOBAL("window_ready")) { FUZZ_BAIL(); }

