int bpp = 4; // RGBA8
unsigned int bytes = (unsigned int)(w * h * bpp);

unsigned char *pixels = (unsigned char *)MemAlloc(bytes);
if (!pixels) { FUZZ_BAIL(); }

Image img = {0};
img.data = pixels;
img.width = w;
img.height = h;
img.mipmaps = 1;
