img.format = 7; // commonly PIXELFORMAT_UNCOMPRESSED_R8G8B8A8

// Call API; ownership of img.data remains with caller per pattern, so free after
SetWindowIcon(img);

MemFree(pixels);
// Lifetime of Image struct itself is stack-local; safe to drop.

// Requires an initialized window
if (!FUZZ_GET_ATTR_INT_GLOBAL("window_ready")) { FUZZ_BAIL(); }

int count = (int)(*FUZZ_PARAM(unsigned int) % 4) + 1; // [1..4]

// Allocate a small array of Images
Image *images = new Image[count];
for (int i = 0; i < count; ++i) {
    // Use small sizes to keep memory under limits
    int w = (int)(*FUZZ_PARAM(unsigned int) % 32) + 1;
    int h = (int)(*FUZZ_PARAM(unsigned int) % 32) + 1;
    int bpp = 4;
    unsigned int bytes = (unsigned int)(w * h * bpp);
    unsigned char *pixels = (unsigned char *)MemAlloc(bytes);
    if (!pixels) {
        // Free any prior allocations before bailing
        for (int j = 0; j < i; ++j) {
            if (images[j].data) MemFree(images[j].data);
        }
        delete[] images;
