import random
import string
from typing import List

# URL string generator for OpenURL fuzzer stub
# Requirements derived from stub and datatype:
# - Null-terminated string (fuzzer API likely appends raw buffer; ensure we include a trailing NUL)
# - Starts with scheme in stub: it prepends "http://" to FUZZ_PARAM_STR(), so our buffer should be the suffix after scheme
# - Keep total length reasonable (< 1024 per stub clamp). We keep our generated suffix <= ~900 bytes.
# - Provide diverse, but valid, URL structures to exercise parsing: hosts, ports, paths, queries, fragments, IPv4/IPv6, punycode-like labels, auth, and file/data/mailto fallbacks.

SAFE_UNRESERVED = string.ascii_letters + string.digits + "-._~"
PCT_HEX = "0123456789ABCDEF"


def _rand_choice(rng: random.Random, seq: List[str]) -> str:
    return rng.choice(seq)


def _label(rng: random.Random, min_len=1, max_len=20) -> str:
    # DNS label: alnum-hyphen, no leading/trailing hyphen, 1-63 chars
    n = rng.randint(min_len, max_len)
    if n == 1:
        return rng.choice(string.ascii_lowercase + string.digits)
    mid_len = max(0, n - 2)
    mid = ''.join(rng.choice(string.ascii_lowercase + string.digits + '-') for _ in range(mid_len))
    # ensure no consecutive hyphen at start/end invalidities
    start = rng.choice(string.ascii_lowercase + string.digits)
    end = rng.choice(string.ascii_lowercase + string.digits)
    return start + mid + end


def _host_dns(rng: random.Random) -> str:
    labels = [_label(rng) for _ in range(rng.randint(1, 4))]
    # sometimes add a TLD-like ending
    tlds = ["com", "org", "net", "io", "dev", "local", "example"]
    if rng.random() < 0.8:
        labels[-1] = labels[-1].rstrip('-') or 'x'
        labels.append(_rand_choice(rng, tlds))
    return '.'.join(labels)


def _host_ipv4(rng: random.Random) -> str:
    return '.'.join(str(rng.randint(0, 255)) for _ in range(4))


def _host_ipv6(rng: random.Random) -> str:
    # Simple full IPv6 or mixed compressed forms inside []
    def h16():
        return ''.join(rng.choice(PCT_HEX.lower()) for _ in range(rng.randint(1, 4)))
    parts = [h16() for _ in range(rng.randint(2, 8))]
    if rng.random() < 0.5 and len(parts) < 8:
        # insert :: compression once
        idx = rng.randint(0, len(parts))
        parts.insert(idx, '')
        parts.insert(idx, '')
    addr = ':'.join(parts)
    return f"[{addr}]"


def _userinfo(rng: random.Random) -> str:
    if rng.random() < 0.3:
        return ''
    user = ''.join(rng.choice(string.ascii_letters + string.digits + '-._') for _ in range(rng.randint(1, 10)))
    if rng.random() < 0.5:
        pwd = ''.join(rng.choice(string.ascii_letters + string.digits + '-._~!$&\'()*+,;=') for _ in range(rng.randint(0, 8)))
        return f"{user}:{pwd}@"
    return f"{user}@"


def _port(rng: random.Random) -> str:
    if rng.random() < 0.5:
        return ''
    return f":{rng.randint(1, 65535)}"


def _pchar(rng: random.Random) -> str:
    # RFC3986 pchar subset plus percent-encoding
    r = rng.random()
    if r < 0.85:
        return rng.choice(SAFE_UNRESERVED + "!$&'()*+,;=:@")
    # percent-escape
    return '%' + rng.choice(PCT_HEX) + rng.choice(PCT_HEX)


def _segment(rng: random.Random, max_len=20) -> str:
    n = rng.randint(0, max_len)
    return ''.join(_pchar(rng) for _ in range(n))


def _path_abs(rng: random.Random) -> str:
    # Absolute path beginning with /
    segs = []
    depth = rng.randint(0, 6)
    for _ in range(depth):
        # include dot-segments occasionally
        if rng.random() < 0.1:
            segs.append('.')
        elif rng.random() < 0.1:
            segs.append('..')
        else:
            segs.append(_segment(rng))
    return '/' + '/'.join(segs)


def _query(rng: random.Random) -> str:
    if rng.random() < 0.5:
        return ''
    pairs = []
    count = rng.randint(1, 6)
    for _ in range(count):
        k = ''.join(rng.choice(SAFE_UNRESERVED) for _ in range(rng.randint(1, 8)))
        v_len = rng.randint(0, 10)
        v = ''.join(rng.choice(SAFE_UNRESERVED + '%') for _ in range(v_len))
        pairs.append(f"{k}={v}")
    return '?' + '&'.join(pairs)


def _fragment(rng: random.Random) -> str:
    if rng.random() < 0.4:
        return ''
    n = rng.randint(0, 12)
    frag = ''.join(rng.choice(SAFE_UNRESERVED + '/?:@') for _ in range(n))
    return '#' + frag


def _http_like_suffix(rng: random.Random) -> str:
    # Generates the portion after "http://" that the stub prepends
    host_type = _rand_choice(rng, ['dns', 'ipv4', 'ipv6'])
    if host_type == 'dns':
        host = _host_dns(rng)
    elif host_type == 'ipv4':
        host = _host_ipv4(rng)
    else:
        host = _host_ipv6(rng)
    userinfo = _userinfo(rng)
    port = _port(rng)
    path = _path_abs(rng)
    query = _query(rng)
    frag = _fragment(rng)
    return f"{userinfo}{host}{port}{path}{query}{frag}"


def _alt_scheme_full_url(rng: random.Random) -> str:
    # Sometimes provide a complete URL with its own scheme, which will yield http://<our full url>
    # Still a valid string but exercises path handling; include data:, file:, mailto:, https:
    scheme = _rand_choice(rng, ['https', 'file', 'data', 'mailto'])
    if scheme == 'https':
        return 'https://' + _http_like_suffix(rng)
    if scheme == 'file':
        # file URLs: file:///absolute/path
        return 'file://' + _path_abs(rng)
    if scheme == 'data':
        med = _rand_choice(rng, ['text/plain', 'image/png', 'application/json'])
        if rng.random() < 0.5:
            payload = ''.join(rng.choice(string.ascii_letters + string.digits + '+/=') for _ in range(rng.randint(8, 64)))
            return f"data:{med};base64,{payload}"
        else:
            txt = ''.join(rng.choice(SAFE_UNRESERVED + '%') for _ in range(rng.randint(0, 40)))
            return f"data:{med},{txt}"
    # mailto
    local = ''.join(rng.choice(string.ascii_letters + string.digits + '._%+-') for _ in range(rng.randint(1, 12)))
    domain = _host_dns(rng)
    params = '' if rng.random() < 0.5 else '?subject=Hi&cc=test@example.com'
    return f"mailto:{local}@{domain}{params}"


def _cap_length(s: str, max_len: int) -> str:
    return s if len(s) <= max_len else s[:max_len]


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # 70% produce a typical http-suffix; 30% produce a complete alternative scheme URL
    if rng.random() < 0.7:
        suffix = _http_like_suffix(rng)
    else:
        suffix = _alt_scheme_full_url(rng)

    # Ensure total length when stub prepends "http://" stays under 1024; target suffix <= 900
    suffix = _cap_length(suffix, 900)

    # Return as bytes with explicit NUL terminator to emphasize C-string termination
    data = suffix.encode('utf-8', errors='strict') + b"\x00"
    # Safety cap per requirements
    return data[:4096]

import random
import struct

# This generator targets a printf-style format string used by the TraceLog stub.
# The stub uses:
#   const char *fmt = "%s %d";
# and supplies two variadic arguments: (const char* from FUZZ_PARAM_STR, int from FUZZ_PARAM(unsigned int)%100000)
# Therefore, any interesting initial buffer should be a valid C string to be consumed by FUZZ_PARAM_STR.
# We aim to produce diverse, printable, null-terminated strings within 256 bytes.

ALPHANUM = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"
PUNCT = "-_.,:;!@#$%^&*()[]{}<>?/~`|+="
WHITES = [" ", "\t", "\n", "\r"]
UNICODE_SAMPLES = [
    "π", "✓", "😀", "汉字", "тест", "áéíóú", "¿¡", "§", "ø", "ß",
]

THEMES = [
    "short", "empty", "long", "path", "json", "csv", "sentence",
    "unicode", "numbers", "punct", "spaces", "mixed"
]

MAX_LEN = 256  # stub truncates to 256


def _rand_word(rng: random.Random, min_len=1, max_len=12):
    n = rng.randint(min_len, max_len)
    return ''.join(rng.choice(ALPHANUM) for _ in range(n))


def _gen_short(rng):
    return _rand_word(rng, 1, 12)


def _gen_empty(rng):
    return ""


def _gen_long(rng):
    # Create a long but valid printable string with varied groups
    parts = []
    while True:
        choice = rng.randint(0, 4)
        if choice == 0:
            parts.append(_rand_word(rng, 3, 16))
        elif choice == 1:
            parts.append(str(rng.randint(0, 10**9)))
        elif choice == 2:
            parts.append(rng.choice(PUNCT) * rng.randint(1, 3))
        elif choice == 3:
            parts.append(rng.choice(WHITES))
        else:
            parts.append(_rand_word(rng, 1, 6))
        s = ''.join(parts)
        if len(s) >= MAX_LEN - 1:
            return s[:MAX_LEN - 1]


def _gen_path(rng):
    # Filesystem-like paths; may include Windows and POSIX styles
    if rng.random() < 0.5:
        # POSIX
        depth = rng.randint(1, 6)
        comps = ["" ] + [ _rand_word(rng,1,10) for _ in range(depth) ]
        if rng.random() < 0.3:
            comps.append('.' + _rand_word(rng,2,4))
        return '/'.join(comps)
    else:
        # Windows
        drive = rng.choice('ABCDEFGHIJKLMNOPQRSTUVWXYZ') + ':'
        depth = rng.randint(1, 6)
        comps = [drive, '\\'] + [ _rand_word(rng,1,10) for _ in range(depth) ]
        if rng.random() < 0.3:
            comps[-1] += '.' + _rand_word(rng,2,4)
        return ''.join(comps)


def _gen_json(rng):
    # Small JSON-like content
    keys = ["msg", "id", "ok", "val", "pi", "name"]
    obj = {
        rng.choice(keys): _rand_word(rng, 3, 10),
        rng.choice(keys): rng.randint(0, 99999),
        rng.choice(keys): rng.choice(["true", "false"])
    }
    parts = ["{"]
    first = True
    for k, v in obj.items():
        if not first:
            parts.append(",")
        first = False
        if isinstance(v, int):
            parts.append(f"\"{k}\":{v}")
        elif v in ("true", "false"):
            parts.append(f"\"{k}\":{v}")
        else:
            parts.append(f"\"{k}\":\"{v}\"")
    parts.append("}")
    return ''.join(parts)


def _gen_csv(rng):
    cols = rng.randint(2, 6)
    row = []
    for _ in range(cols):
        t = rng.random()
        if t < 0.33:
            row.append(_rand_word(rng, 1, 8))
        elif t < 0.66:
            row.append(str(rng.randint(0, 100000)))
        else:
            # quoted with commas and spaces
            frag = _rand_word(rng, 2, 5) + ', ' + _rand_word(rng, 2, 5)
            row.append('"' + frag + '"')
    return ','.join(row)


def _gen_sentence(rng):
    n = rng.randint(3, 20)
    words = [_rand_word(rng, 1, 12) for _ in range(n)]
    s = ' '.join(words)
    if rng.random() < 0.5:
        s += rng.choice(['.', '!', '?'])
    return s


def _gen_unicode(rng):
    # Combine ASCII with some unicode samples
    parts = []
    n = rng.randint(1, 8)
    for _ in range(n):
        parts.append(_rand_word(rng, 1, 6))
        parts.append(rng.choice([" ", "-", ":"]))
        parts.append(rng.choice(UNICODE_SAMPLES))
        parts.append(rng.choice([" ", "/"]))
    s = ''.join(parts)
    return s[:MAX_LEN - 1]


def _gen_numbers(rng):
    nums = [str(rng.randint(-10**9, 10**9)) for _ in range(rng.randint(1, 20))]
    return ' '.join(nums)


def _gen_punct(rng):
    return ''.join(rng.choice(PUNCT) for _ in range(rng.randint(1, 64)))


def _gen_spaces(rng):
    return ''.join(rng.choice(WHITES) for _ in range(rng.randint(1, 64)))


def _gen_mixed(rng):
    gens = [_gen_short, _gen_numbers, _gen_punct, _gen_sentence, _gen_unicode]
    parts = []
    for _ in range(rng.randint(2, 6)):
        parts.append(rng.choice(gens)(rng))
    s = ' '.join(parts)
    return s[:MAX_LEN - 1]


GEN_MAP = {
    "short": _gen_short,
    "empty": _gen_empty,
    "long": _gen_long,
    "path": _gen_path,
    "json": _gen_json,
    "csv": _gen_csv,
    "sentence": _gen_sentence,
    "unicode": _gen_unicode,
    "numbers": _gen_numbers,
    "punct": _gen_punct,
    "spaces": _gen_spaces,
    "mixed": _gen_mixed,
}


def generate(seed: int) -> bytes:
    """
    Produce a bytes buffer intended for FUZZ_PARAM_STR in the TraceLog stub.
    The buffer is a single null-terminated UTF-8 string, length <= 256.
    """
    rng = random.Random(seed)

    theme = rng.choice(THEMES)
    s = GEN_MAP[theme](rng)

    # Ensure length limit and NUL termination for C consumption
    if len(s) >= MAX_LEN:
        s = s[:MAX_LEN - 1]

    # Occasionally craft edge-interesting specific literals
    if rng.random() < 0.15:
        specials = [
            "",  # truly empty
            "0", "-1", "2147483647", "-2147483648",
            "true", "false",
            "NULL", "(null)",
            "C:\\temp\\file.txt", "/tmp/file.txt",
            "hello\nworld", "tab\tseparated",
        ]
        s = rng.choice(specials)

    # Encode to UTF-8 and add explicit NUL terminator to make a C-string
    b = s.encode('utf-8', errors='ignore') + b"\x00"
    # Guard final size
    return b[:MAX_LEN]
